249	std::unique_ptr<DHTResponseMessage>
250	DHTMessageFactoryImpl::createResponseMessage(const std::string& messageType,
251	                                             const Dict* dict,
252	                                             const std::string& ipaddr,
253	                                             uint16_t port)
254	{
255	  const String* transactionID = getString(dict, DHTMessage::T);
256	  const String* y = getString(dict, DHTMessage::Y);
257	  if (y->s() == DHTUnknownMessage::E) {
258	    // for now, just report error message arrived and throw exception.
259	    const List* e = getList(dict, DHTUnknownMessage::E);
260	    if (e->size() == 2) {
261	      A2_LOG_INFO(fmt("Received Error DHT message. code=%" PRId64 ", msg=%s",
262	                      getInteger(e, 0)->i(),
263	                      util::percentEncode(getString(e, 1)->s()).c_str()));
264	    }
265	    else {
266	      A2_LOG_DEBUG("e doesn't have 2 elements.");
267	    }
268	    throw DL_ABORT_EX("Received Error DHT message.");
269	  }
270	  else if (y->s() != DHTResponseMessage::R) {
271	    throw DL_ABORT_EX(fmt("Malformed DHT message. y != r: y=%s",
272	                          util::percentEncode(y->s()).c_str()));
273	  }
274	  const Dict* rDict = getDictionary(dict, DHTResponseMessage::R);
275	  const String* id = getString(rDict, DHTMessage::ID);
276	  validateID(id);
277	  auto remoteNode = getRemoteNode(id->uc(), ipaddr, port);
278	  auto msg = std::unique_ptr<DHTResponseMessage>{};
279	  if (messageType == DHTPingReplyMessage::PING) {
280	    msg = createPingReplyMessage(remoteNode, id->uc(), transactionID->s());
281	  }
282	  else if (messageType == DHTFindNodeReplyMessage::FIND_NODE) {
283	    msg = createFindNodeReplyMessage(remoteNode, dict, transactionID->s());
284	  }
285	  else if (messageType == DHTGetPeersReplyMessage::GET_PEERS) {
286	    msg = createGetPeersReplyMessage(remoteNode, dict, transactionID->s());
287	  }
288	  else if (messageType == DHTAnnouncePeerReplyMessage::ANNOUNCE_PEER) {
289	    msg = createAnnouncePeerReplyMessage(remoteNode, transactionID->s());
290	  }
291	  else {
292	    throw DL_ABORT_EX(fmt("Unsupported message type: %s", messageType.c_str()));
293	  }
294	  setVersion(msg.get(), dict);
295	  return msg;
296	}
