299	const std::string& getDefaultVersion()
300	{
301	  static std::string version;
302	  if (version.empty()) {
303	    uint16_t vnum16 = htons(DHT_VERSION);
304	    unsigned char buf[] = {'A', '2', 0, 0};
305	    char* vnump = reinterpret_cast<char*>(&vnum16);
306	    memcpy(buf + 2, vnump, 2);
307	    version.assign(&buf[0], &buf[4]);
308	  }
309	  return version;
310	}
