365	
366	void DHTMessageFactoryImpl::extractNodes(
367	    std::vector<std::shared_ptr<DHTNode>>& nodes, const unsigned char* src,
368	    size_t length)
369	{
370	  int unit = bittorrent::getCompactLength(family_) + 20;
371	  if (length % unit != 0) {
372	    throw DL_ABORT_EX(fmt("Nodes length is not multiple of %d", unit));
373	  }
374	  for (size_t offset = 0; offset < length; offset += unit) {
375	    auto node = std::make_shared<DHTNode>(src + offset);
376	    auto addr =
377	        bittorrent::unpackcompact(src + offset + DHT_ID_LENGTH, family_);
378	    if (addr.first.empty()) {
379	      continue;
380	    }
381	    node->setIPAddress(addr.first);
382	    node->setPort(addr.second);
383	    nodes.push_back(std::move(node));
384	  }
385	}
386	
387	std::unique_ptr<DHTFindNodeReplyMessage>
388	DHTMessageFactoryImpl::createFindNodeReplyMessage(
389	    const std::shared_ptr<DHTNode>& remoteNode, const Dict* dict,
390	    const std::string& transactionID)
391	{
392	  const String* nodesData = downcast<String>(
393	      getDictionary(dict, DHTResponseMessage::R)
394	          ->get(family_ == AF_INET ? DHTFindNodeReplyMessage::NODES
395	                                   : DHTFindNodeReplyMessage::NODES6));
396	  std::vector<std::shared_ptr<DHTNode>> nodes;
397	  if (nodesData) {
398	    extractNodes(nodes, nodesData->uc(), nodesData->s().size());
399	  }
400	  return createFindNodeReplyMessage(remoteNode, std::move(nodes),
401	                                    transactionID);
402	}
