  auto m = make_unique<DHTAnnouncePeerMessage>(localNode_, remoteNode, infoHash,
                                               tcpPort, token, transactionID);
  m->setPeerAnnounceStorage(peerAnnounceStorage_);
  m->setTokenTracker(tokenTracker_);
