366	void DHTMessageFactoryImpl::extractNodes(
367	    std::vector<std::shared_ptr<DHTNode>>& nodes, const unsigned char* src,
368	    size_t length)
369	{
370	  int unit = bittorrent::getCompactLength(family_) + 20;
371	  if (length % unit != 0) {
372	    throw DL_ABORT_EX(fmt("Nodes length is not multiple of %d", unit));
373	  }
374	  for (size_t offset = 0; offset < length; offset += unit) {
375	    auto node = std::make_shared<DHTNode>(src + offset);
376	    auto addr =
377	        bittorrent::unpackcompact(src + offset + DHT_ID_LENGTH, family_);
378	    if (addr.first.empty()) {
379	      continue;
380	    }
381	    node->setIPAddress(addr.first);
382	    node->setPort(addr.second);
383	    nodes.push_back(std::move(node));
384	  }
385	}
