393	      getDictionary(dict, DHTResponseMessage::R)
394	          ->get(family_ == AF_INET ? DHTFindNodeReplyMessage::NODES
395	                                   : DHTFindNodeReplyMessage::NODES6));
396	  std::vector<std::shared_ptr<DHTNode>> nodes;
397	  if (nodesData) {
398	    extractNodes(nodes, nodesData->uc(), nodesData->s().size());
399	  }
400	  return createFindNodeReplyMessage(remoteNode, std::move(nodes),
401	                                    transactionID);
402	}
