424	  const Dict* rDict = getDictionary(dict, DHTResponseMessage::R);
425	  const String* nodesData = downcast<String>(
426	      rDict->get(family_ == AF_INET ? DHTGetPeersReplyMessage::NODES
427	                                    : DHTGetPeersReplyMessage::NODES6));
428	  std::vector<std::shared_ptr<DHTNode>> nodes;
429	  if (nodesData) {
430	    extractNodes(nodes, nodesData->uc(), nodesData->s().size());
431	  }
432	  const List* valuesList =
433	      downcast<List>(rDict->get(DHTGetPeersReplyMessage::VALUES));
434	  std::vector<std::shared_ptr<Peer>> peers;
435	  size_t clen = bittorrent::getCompactLength(family_);
436	  if (valuesList) {
437	    for (auto& elem : *valuesList) {
438	      const String* data = downcast<String>(elem);
439	      if (data && data->s().size() == clen) {
440	        auto addr = bittorrent::unpackcompact(data->uc(), family_);
441	        if (addr.first.empty()) {
442	          continue;
443	        }
444	        peers.push_back(std::make_shared<Peer>(addr.first, addr.second));
445	      }
446	    }
447	  }
448	  const String* token = getString(rDict, DHTGetPeersReplyMessage::TOKEN);
449	  return createGetPeersReplyMessage(remoteNode, std::move(nodes),
450	                                    std::move(peers), token->s(),
451	                                    transactionID);
452	}
