61	DHTGetPeersMessage::DHTGetPeersMessage(
62	    const std::shared_ptr<DHTNode>& localNode,
63	    const std::shared_ptr<DHTNode>& remoteNode, const unsigned char* infoHash,
64	    const std::string& transactionID)
65	    : DHTQueryMessage{localNode, remoteNode, transactionID},
66	      peerAnnounceStorage_{nullptr},
67	      tokenTracker_{nullptr},
68	      btRegistry_{nullptr},
