74	void DHTGetPeersMessage::addLocalPeer(std::vector<std::shared_ptr<Peer>>& peers)
75	{
76	  if (!btRegistry_) {
77	    return;
78	  }
79	
80	  auto& dctx = btRegistry_->getDownloadContext(
81	      std::string(infoHash_, infoHash_ + DHT_ID_LENGTH));
82	
83	  if (!dctx) {
84	    return;
85	  }
86	
87	  auto group = dctx->getOwnerRequestGroup();
88	  auto& option = group->getOption();
89	  auto& externalIP = option->get(PREF_BT_EXTERNAL_IP);
90	
91	  if (externalIP.empty()) {
92	    return;
93	  }
94	
95	  std::array<uint8_t, sizeof(struct in6_addr)> dst;
96	  if (inetPton(family_, externalIP.c_str(), dst.data()) == -1) {
97	    return;
98	  }
99	
100	  auto tcpPort = btRegistry_->getTcpPort();
101	  if (std::find_if(std::begin(peers), std::end(peers),
102	                   [&externalIP, tcpPort](const std::shared_ptr<Peer>& peer) {
103	                     return peer->getIPAddress() == externalIP &&
104	                            peer->getPort() == tcpPort;
105	                   }) != std::end(peers)) {
106	    return;
107	  }
108	
109	  peers.push_back(std::make_shared<Peer>(externalIP, tcpPort));
110	}
