112	void DHTGetPeersMessage::doReceivedAction()
113	{
114	  std::string token = tokenTracker_->generateToken(
115	      infoHash_, getRemoteNode()->getIPAddress(), getRemoteNode()->getPort());
116	  std::vector<std::shared_ptr<Peer>> peers;
117	  peerAnnounceStorage_->getPeers(peers, infoHash_);
118	
119	  // Check to see localhost has the contents which has same infohash
120	  addLocalPeer(peers);
121	
122	  std::vector<std::shared_ptr<DHTNode>> nodes;
123	  getRoutingTable()->getClosestKNodes(nodes, infoHash_);
124	  getMessageDispatcher()->addMessageToQueue(
125	      getMessageFactory()->createGetPeersReplyMessage(
126	          getRemoteNode(), std::move(nodes), std::move(peers), token,
127	          getTransactionID()));
128	}
