96	      if (clen >= 0 && compactlen == cclen) {
97	        last = std::copy_n((*i)->getID(), DHT_ID_LENGTH, last);
98	        last = std::copy_n(std::begin(compact), compactlen, last);
99	        ++k;
100	      }
101	    }
102	    rDict->put(family_ == AF_INET ? NODES : NODES6,
103	               String::g(std::begin(buffer), last));
104	  }
105	  if (!values_.empty()) {
106	    // Limit the size of values list.  The maximum size of UDP datagram
107	    // is limited to 65535 bytes. aria2 uses 20bytes token and 2byte
108	    // transaction ID. The size of get_peers reply message without
109	    // values list and nodes is 87bytes:
110	    //
111	    // d1:rd2:id20:aaaaaaaaaaaaaaaaaaaa5:token20:aaaaaaaaaaaaaaaaaaaa
112	    // 6:valueslee1:t2:bb1:y1:re
113	    //
114	    // nodes are 38 bytes per host for IPv6 and the number of hosts is
115	    // K(=8) max. So without values list, we already 87+38*8+4 = 395.
116	    //
117	    // Because of Path MTU Discovery, UDP packet size which need not
118	    // to be fragmented is much smaller. Since Linux uses Path MTU
119	    // Discovery by default and returning ICMP message might be
120	    // filtered, we should avoid fragmentation.  MTU of pppoe is 1492
121	    // max according to RFC2516.  We use maximum packet size to be
122	    // 1024. Since it contains 20 bytes IP header and 8 bytes UDP
123	    // header and 395 bytes reply message template described above, We
124	    // can carry (1024-28-395)/(18+3) = 28 peer info. Since DHT spec
125	    // doesn't specify the maximum size of token, reply message
126	    // template may get bigger than 395 bytes. So we use 25 as maximum
127	    // number of peer info that a message can carry.
128	    constexpr size_t MAX_VALUES_SIZE = 25;
129	    auto valuesList = List::g();
130	    for (auto i = std::begin(values_);
131	         i != std::end(values_) && valuesList->size() < MAX_VALUES_SIZE; ++i) {
132	      std::array<unsigned char, COMPACT_LEN_IPV6> compact;
133	      const auto clen = bittorrent::getCompactLength(family_);
134	      auto compactlen = bittorrent::packcompact(
135	          compact.data(), (*i)->getIPAddress(), (*i)->getPort());
136	      auto cclen =
137	          static_cast<std::make_unsigned<decltype(clen)>::type>((clen));
138	      if (clen > 0 && compactlen == cclen) {
139	        valuesList->append(String::g(compact.data(), compactlen));
140	      }
141	    }
142	    rDict->put(VALUES, std::move(valuesList));
143	  }
144	  return rDict;
145	}
146	
147	const std::string& DHTGetPeersReplyMessage::getMessageType() const
148	{
149	  return GET_PEERS;
150	}
151	
152	void DHTGetPeersReplyMessage::accept(DHTMessageCallback* callback)
153	{
154	  callback->visit(this);
155	}
156	
157	std::string DHTGetPeersReplyMessage::toStringOptional() const
158	{
159	  return fmt("token=%s, values=%lu, nodes=%lu", util::toHex(token_).c_str(),
160	             static_cast<unsigned long>(values_.size()),
161	             static_cast<unsigned long>(closestKNodes_.size()));
162	}
163	
164	void DHTGetPeersReplyMessage::setClosestKNodes(
165	    std::vector<std::shared_ptr<DHTNode>> closestKNodes)
166	{
167	  closestKNodes_ = std::move(closestKNodes);
168	}
169	
170	void DHTGetPeersReplyMessage::setValues(
171	    std::vector<std::shared_ptr<Peer>> peers)
172	{
173	  values_ = std::move(peers);
174	}
175	
176	} // namespace aria2
