52	namespace aria2 {
53	
54	DHTMessageTracker::DHTMessageTracker()
55	    : routingTable_{nullptr}, factory_{nullptr}
56	{
57	}
58	
59	void DHTMessageTracker::addMessage(DHTMessage* message,
60	                                   std::chrono::seconds timeout,
61	                                   std::unique_ptr<DHTMessageCallback> callback)
62	{
63	  entries_.push_back(make_unique<DHTMessageTrackerEntry>(
64	      message->getRemoteNode(), message->getTransactionID(),
65	      message->getMessageType(), std::move(timeout), std::move(callback)));
66	}
67	
68	std::pair<std::unique_ptr<DHTResponseMessage>,
69	          std::unique_ptr<DHTMessageCallback>>
70	DHTMessageTracker::messageArrived(const Dict* dict, const std::string& ipaddr,
71	                                  uint16_t port)
72	{
73	  const String* tid = downcast<String>(dict->get(DHTMessage::T));
74	  if (!tid) {
75	    throw DL_ABORT_EX(
76	        fmt("Malformed DHT message. From:%s:%u", ipaddr.c_str(), port));
77	  }
78	  A2_LOG_DEBUG(fmt("Searching tracker entry for TransactionID=%s, Remote=%s:%u",
79	                   util::toHex(tid->s()).c_str(), ipaddr.c_str(), port));
80	  for (auto i = std::begin(entries_), eoi = std::end(entries_); i != eoi; ++i) {
81	    if ((*i)->match(tid->s(), ipaddr, port)) {
82	      auto entry = std::move(*i);
83	      entries_.erase(i);
84	      A2_LOG_DEBUG("Tracker entry found.");
85	      auto& targetNode = entry->getTargetNode();
86	      try {
87	        auto message = factory_->createResponseMessage(
88	            entry->getMessageType(), dict, targetNode->getIPAddress(),
89	            targetNode->getPort());
90	
91	        auto rtt = std::chrono::duration_cast<std::chrono::milliseconds>(
92	            entry->getElapsed());
93	        A2_LOG_DEBUG(
94	            fmt("RTT is %" PRId64 "", static_cast<int64_t>(rtt.count())));
95	        message->getRemoteNode()->updateRTT(rtt);
96	        if (*targetNode != *message->getRemoteNode()) {
97	          // Node ID has changed. Drop previous node ID from
98	          // DHTRoutingTable
99	          A2_LOG_DEBUG(
100	              fmt("Node ID has changed: old:%s, new:%s",
101	                  util::toHex(targetNode->getID(), DHT_ID_LENGTH).c_str(),
102	                  util::toHex(message->getRemoteNode()->getID(), DHT_ID_LENGTH)
103	                      .c_str()));
104	          routingTable_->dropNode(targetNode);
105	        }
106	        return std::make_pair(std::move(message), entry->popCallback());
107	      }
108	      catch (RecoverableException& e) {
109	        handleTimeoutEntry(entry.get());
110	        throw;
111	      }
112	    }
113	  }
114	  A2_LOG_DEBUG("Tracker entry not found.");
115	  return std::pair<std::unique_ptr<DHTResponseMessage>,
116	                   std::unique_ptr<DHTMessageCallback>>{};
117	}
118	
119	void DHTMessageTracker::handleTimeoutEntry(DHTMessageTrackerEntry* entry)
120	{
121	  try {
122	    auto& node = entry->getTargetNode();
123	    A2_LOG_DEBUG(fmt("Message timeout: To:%s:%u", node->getIPAddress().c_str(),
124	                     node->getPort()));
125	    node->updateRTT(std::chrono::duration_cast<std::chrono::milliseconds>(
126	        entry->getElapsed()));
127	    node->timeout();
128	    if (node->isBad()) {
129	      A2_LOG_DEBUG(fmt("Marked bad: %s:%u", node->getIPAddress().c_str(),
130	                       node->getPort()));
131	      routingTable_->dropNode(node);
132	    }
133	    auto& callback = entry->getCallback();
134	    if (callback) {
135	      callback->onTimeout(node);
136	    }
137	  }
138	  catch (RecoverableException& e) {
139	    A2_LOG_INFO_EX("Exception thrown while handling timeouts.", e);
140	  }
141	}
142	
143	void DHTMessageTracker::handleTimeout()
144	{
145	  entries_.erase(
146	      std::remove_if(std::begin(entries_), std::end(entries_),
147	                     [&](const std::unique_ptr<DHTMessageTrackerEntry>& ent) {
148	                       if (ent->isTimeout()) {
149	                         handleTimeoutEntry(ent.get());
150	                         return true;
151	                       }
152	                       else {
153	                         return false;
154	                       }
155	                     }),
156	      std::end(entries_));
157	}
158	
159	const DHTMessageTrackerEntry*
160	DHTMessageTracker::getEntryFor(const DHTMessage* message) const
161	{
162	  for (auto& ent : entries_) {
163	    if (ent->match(message->getTransactionID(),
164	                   message->getRemoteNode()->getIPAddress(),
165	                   message->getRemoteNode()->getPort())) {
166	      return ent.get();
167	    }
168	  }
169	  return nullptr;
